{
  "probability": 0.98,
  "range_low": 0.92,
  "range_high": 0.99,
  "summary": [
    " February 2026 mortality pace reached 524 by Feb 10 and 606 by Feb 23–24, making end-March totals near 900 plausible if the pace persists.",
    " High ongoing departure pressure (Tunisia/Libya) and adverse weather increase risk of additional fatalities into March.",
    " Limited search-and-rescue capacity due to funding and operational constraints further tilts toward higher fatalities, while policy crackdowns could dampen crossings.",
    " Data undercount and reporting lags inject uncertainty, but the balance of factors supports a very high probability for hitting 900 by end-March."
  ],
  "confidence": "high",
  "narrative": "The February 2026 death toll pace implies a high likelihood of reaching 900 deaths by end-March if conditions remain unfavorable. While SAR constraints and weather boost risk, countervailing policy crackdowns and data gaps add uncertainty, yielding a calibrated near-certain posterior around 0.98.",
  "justification": {
    "anchor": {
      "probability": 0.60,
      "basis": "Baseline reference class: IOM Missing Migrants Project Central Mediterranean fatalities. Anchored on February 2026 pace (524 by Feb 10; 533 by Feb 16; 606 by Feb 23–24) to project end-March outcomes; 0.60 reflects an initial baseline before factor updates."
    },
    "factor_updates": [
      {
        "factor": "Observed pace Feb 2026",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "The rapid accumulation through February suggests a high probability of reaching 900 by the end of March if the pace continues."
      },
      {
        "factor": "March weather and crossings risk",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Forecasted storms and rough seas keep crossing risk elevated, sustaining a high fatality rate into March."
      },
      {
        "factor": "Tunisia departure surge driving more attempts",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Continued high departure pressure increases vessel exposure and potential fatalities."
      },
      {
        "factor": "SAR capacity constraints due to funding cuts",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Limited rescues can translate to more deaths per crossing."
      },
      {
        "factor": "Policy crackdown reducing crossings",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter controls could reduce attempts and fatalities, offsetting some risk."
      },
      {
        "factor": "Data undercount and reporting lag",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Incomplete tallies may understate the true toll, potentially pushing totals higher once revisions occur."
      }
    ],
    "synthesis_rationale": "Starting from a moderate anchor, strong up-update signals from Feb 2026 pace dominate, with weather, departures, and SAR constraints pushing risk higher; policy crackdowns provide a countervailing down-update that is not enough to offset the aggregate pressure. Given correlations among factors and potential reporting gaps, the calibrated posterior lands at 0.98 with a tight range."
  }
}

{
  "probability": 0.98,
  "range_low": 0.95,
  "range_high": 0.99,
  "summary": [
    "Feb 2026 pace (approximately 606 deaths by late Feb) implies a high likelihood of reaching or exceeding 900 deaths by end-March if the pace persists.",
    "Key risk multipliers (weather/sea conditions, ongoing departure pressure, and SAR constraints) push the trajectory upward, while policy crackdowns provide countervailing pressure.",
    "Reporting gaps and potential revisions could mean the true toll is higher, supporting a near-certainty level within the anchor’s upper tail."
  ],
  "confidence": "high",
  "narrative": "Early-2026 data show an unusually deadly start to the year in the central Mediterranean, with around 606 deaths by late February. If March maintains that pace and reporting gaps do not undercount, the chance of reaching 900 deaths before April remains extremely high, justifying a posterior near 0.98 with a narrow uncertainty band.",
  "justification": {
    "anchor": {
      "probability": 0.80,
      "basis": "Anchor on the pace through February 2026 (e.g., 524 by Feb 10; 606 by Feb 23–24) within the IOM Missing Migrants Project Central Mediterranean route, used to calibrate end-March risk."
    },
    "factor_updates": [
      {
        "factor": "Sustained high mortality pace through March 2026 (continuation of February 2026 trend)",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "Counts around 524–606 by late Feb imply that continuing that pace into March would push total toward or beyond 900 before April."
      },
      {
        "factor": "Adverse weather events and winter storms increasing risk on Mediterranean crossings",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Storms and rough seas have been linked to higher fatalities; continued adverse conditions could sustain high mortality in March."
      },
      {
        "factor": "Diminished search-and-rescue capacity due to funding cuts",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Reduced SAR capacity can translate into more lives lost, elevating the death count if operations do not scale up."
      },
      {
        "factor": "Policy/regulatory crackdown reducing departures in some origin countries",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stricter controls could reduce crossing attempts and thus fatalities, introducing downward pressure on the tally."
      },
      {
        "factor": "Data reporting lags and potential undercount/revisions to tallies",
        "direction": "up",
        "magnitude": "weak",
        "rationale": "Underreporting at sea means the official tallies may rise with revisions, adding upward pressure albeit with uncertainty."
      },
      {
        "factor": "SAR capacity improvements potentially mitigating fatalities",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "If SAR capacity improves, more rescues could occur, dampening the end-March death toll."
      }
    ],
    "synthesis_rationale": "Starting from an anchor reflecting February 2026 pace, the updates predominantly push probability upward due to a high observed death rate and plausible continuation into March, tempered by a few downward pressures (policy crackdowns and potential SAR improvements). Given the unusually high early-year pace and persistent risk factors, calibration assigns a high posterior near 0.98, while acknowledging reporting gaps and the possibility of March conditions altering the trajectory."
  }
}
